theme.css:
/* theme: Tension in Amber | A day of waiting — a historic Senate race hanging by a thread, markets in freefall, and governments yet to form — cast in the restless glow of a stalled moment. */
/* mood: tense */
/* layout: hero=split; major-events=timeline/stack; political-news=lede/stack; financial-news=stat/grid-2; entertainment-news=numbered/grid-3; sports=banner/grid-2; music-releases=plain/stack; stock-analysis=stat/masonry; outlook=tile/stack */

.diary-page {
  --paper: #1d1607;
  --paper-alt: #2a2112;
  --ink: #f7e8c8;
  --ink-soft: #e0d0a8;
  --muted: #b8a87f;
  --accent: #ffad33;
  --accent-ink: #1a1405;
  --rule: #4a3d22;
  --font-display: var(--ff-space-grotesk), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 2px solid var(--accent);
  position: relative;
}

.diary-page .diary-hero::after {
  content: "⚖";
  position: absolute;
  right: 2rem;
  top: 2rem;
  font-size: 3rem;
  color: var(--accent);
  opacity: 0.6;
}

.diary-page .diary-kicker {
  font-family: var(--font-ui);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent);
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 6.5vw, 5.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 0.98;
  color: var(--ink);
  text-transform: uppercase;
}

.diary-page .diary-summary {
  font-size: clamp(1.05rem, 2vw, 1.3rem);
  line-height: 1.6;
  color: var(--ink-soft);
  border-left: 3px solid var(--accent);
  padding-left: 1.25rem;
}

.diary-page .diary-theme-note {
  font-family: var(--font-ui);
  font-size: 0.8rem;
  color: var(--muted);
  letter-spacing: 0.03em;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 700;
  padding: 0.15rem 0.7rem;
  border-radius: 0;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-label {
  color: var(--accent);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-bottom:hover {
  color: var(--ink);
}

.diary-page .diary-toc-link.is-active {
  color: var(--ink);
  border-left-color: var(--accent);
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  position: relative;
}

.diary-page .diary-section-head {
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--accent);
  background: var(--paper-alt);
  padding: 0.25rem 0.75rem;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 3.4vw, 2.6rem);
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--ink);
  text-transform: uppercase;
}

.diary-page .diary-prose {
  font-size: 1.12rem;
  line-height: 1.75;
  color: var(--ink-soft);
}

.diary-page .diary-prose h3 {
  font-family: var(--font-ui);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--ink);
  text-transform: uppercase;
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid var(--accent);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
  border-bottom-color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-prose code,
.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-stories--stack .diary-card--plain + .diary-card--plain {
  border-top-color: var(--rule);
}

.diary-page .diary-card--outline .diary-card-inner {
  border-color: var(--rule);
  border-radius: 0;
  background: var(--paper-alt);
}

.diary-page .diary-card--elevated .diary-card-inner {
  background: var(--paper-alt);
  border-color: var(--rule);
  border-radius: 0;
  box-shadow: 0 2px 8px rgb(0 0 0 / 0.3);
}

.diary-page .diary-card--banner .diary-card-inner {
  border-color: var(--rule);
  border-radius: 0;
}

.diary-page .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 1.1rem;
  padding: 0.9rem 1.25rem;
}

.diary-page .diary-card--banner .diary-card-body {
  padding: 1.25rem;
  background: var(--paper-alt);
}

.diary-page .diary-card--split .diary-card-inner {
  border-top-color: var(--accent);
  border-top-width: 2px;
  padding-top: 1.25rem;
}

.diary-page .diary-card--numbered .diary-card-index {
  font-family: var(--font-display);
  font-size: 2.8rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: -0.02em;
}

.diary-page .diary-card--numbered .diary-card-inner {
  border-left: 2px solid var(--rule);
  padding-left: 1.25rem;
}

.diary-page .diary-card--numbered .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-card-lede {
  border-left-color: var(--accent);
  font-family: var(--font-display);
  font-size: 1.35rem;
  color: var(--ink);
  line-height: 1.4;
}

.diary-page .diary-card--stat .diary-card-inner {
  border-top: 3px solid var(--accent);
  padding-top: 1rem;
}

.diary-page .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 12cqi, 3.8rem);
  font-weight: 700;
  color: var(--accent);
  letter-spacing: -0.02em;
}

.diary-page .diary-card--timeline .diary-card-inner {
  padding-left: 2rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  left: 0.35rem;
  width: 2px;
  background: var(--rule);
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  left: 0;
  top: 0.5rem;
  width: 0.7rem;
  height: 0.7rem;
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper-alt);
}

.diary-page .diary-card--timeline .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
  padding: 1.5rem;
}

.diary-page .diary-card--tile .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--ink);
  text-transform: uppercase;
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 600;
  line-height: 1.2;
  color: var(--ink);
}

.diary-page .diary-card-body {
  font-size: 1.04rem;
  line-height: 1.7;
  color: var(--ink-soft);
}

.diary-page .diary-stories--stack .diary-card-body {
  font-size: 1.12rem;
  line-height: 1.75;
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  font-family: var(--font-ui);
  font-size: 0.72rem;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-card--banner .diary-card-thread {
  background: var(--paper-alt);
  border-color: var(--accent);
  color: var(--accent);
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark-change {
  font-weight: 600;
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark .diary-spark-line polyline {
  stroke: var(--accent);
  stroke-width: 1.5;
  fill: none;
}

.diary-page .diary-spark.is-up .diary-spark-line polyline {
  stroke: var(--accent);
}

.diary-page .diary-footer {
  border-top-color: var(--rule);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    border-left: 1px solid var(--rule);
  }
}

@media (prefers-reduced-motion: reduce) {
  .diary-page *,
  .diary-page *::before,
  .diary-page *::after {
    animation: none !important;
    transition: none !important;
  }
}
